package com.office.lanmonitor;
import org.junit.*;
import static org.junit.Assert.*;
import java.net.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
public class HlsMuxerTest {
 private HlsMuxer sample(){HlsMuxer m=new HlsMuxer();m.setAudio(48000);byte[] frame={0,0,0,1,0x65,1,2,3};for(int i=0;i<5;i++){m.video(frame,i*2000000L,true);m.audio(new byte[]{1,2,3},i*2000000L);}return m;}
 @Test public void segmentsHaveTsSyncPatPmtAndValidCrc(){HlsMuxer m=sample();assertEquals(4,m.count());byte[] ts=m.segment(0);assertEquals(0,ts.length%188);for(int i=0;i<ts.length;i+=188)assertEquals(0x47,ts[i]&255);for(int packet=0;packet<2;packet++){int base=packet*188;int adaptation=(ts[base+3]>>4)&3;int offset=base+4;if(adaptation==3)offset+=1+(ts[offset]&255);offset+=1+(ts[offset]&255);int length=3+(((ts[offset+1]&15)<<8)|(ts[offset+2]&255));assertEquals(0,HlsMuxer.crc(java.util.Arrays.copyOfRange(ts,offset,offset+length)));}String playlist=new String(m.playlist(),StandardCharsets.US_ASCII);assertTrue(playlist.contains("#EXT-X-TARGETDURATION:2"));assertTrue(playlist.contains("segment-0.ts"));}
 @Test public void liveWindowEvictsOldSegments(){HlsMuxer m=sample();for(int i=5;i<15;i++)m.video(new byte[]{0,0,1,0x65},i*2000000L,true);assertEquals(6,m.count());assertNull(m.segment(0));assertFalse(new String(m.playlist(),StandardCharsets.US_ASCII).contains("segment-0.ts"));}
 @Test public void originServesCorsAndRejectsOtherPaths()throws Exception{HlsMuxer m=sample();try(StreamServer server=new StreamServer(m)){URL u=new URL(server.url("127.0.0.1"));HttpURLConnection c=(HttpURLConnection)u.openConnection();assertEquals(200,c.getResponseCode());assertEquals("*",c.getHeaderField("Access-Control-Allow-Origin"));assertTrue(new String(c.getInputStream().readAllBytes(),StandardCharsets.US_ASCII).contains("#EXTM3U"));c.disconnect();HttpURLConnection denied=(HttpURLConnection)new URL("http://127.0.0.1:"+u.getPort()+"/live.m3u8").openConnection();assertEquals(404,denied.getResponseCode());denied.disconnect();URL segment=new URL(u,"segment-0.ts");HttpURLConnection range=(HttpURLConnection)segment.openConnection();range.setRequestProperty("Range","bytes=0-187");assertEquals(206,range.getResponseCode());assertEquals(188,range.getInputStream().readAllBytes().length);range.disconnect();}}

 @Test public void lowLatencySegmentsUseHalfSecondKeyframes(){HlsMuxer m=new HlsMuxer(LatencyProfile.LOW);for(int n=0;n<5;n++)m.video(new byte[]{0,0,1,0x65},n*500000L,true);String playlist=new String(m.playlist(),StandardCharsets.US_ASCII);assertEquals(4,m.count());assertTrue(playlist.contains("#EXTINF:0.500"));assertTrue(playlist.contains("#EXT-X-TARGETDURATION:1"));assertTrue(playlist.contains("#EXT-X-START:"));}
 @Test public void continuousClientWaitsForKeyframeAndReceivesTables()throws Exception{HlsMuxer m=new HlsMuxer(LatencyProfile.LOW);HlsMuxer.LiveClient client=m.subscribe();m.video(new byte[]{0,0,1,0x41},0,false);assertTrue(client.packets.isEmpty());m.video(new byte[]{0,0,1,0x65},500000,true);byte[] pat=client.next(),pmt=client.next(),pes=client.next();assertEquals(0x47,pat[0]&255);assertEquals(0,((pat[1]&31)<<8)|(pat[2]&255));assertEquals(4096,((pmt[1]&31)<<8)|(pmt[2]&255));assertEquals(256,((pes[1]&31)<<8)|(pes[2]&255));m.closeClients();assertTrue(client.closed());}
}
